// src/components/layout/AdminLayout.js
import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

const NAV = [
  { to:'/admin',         label:'Overview',   icon:'📊', exact:true },
  { to:'/admin/p2h',     label:'P2H',        icon:'📋' },
  { to:'/admin/spk',     label:'SPK',        icon:'🔧' },
  { to:'/admin/storing', label:'Storing',    icon:'📍' },
  { to:'/admin/unit',    label:'Data Unit',  icon:'🚛' },
];

const S = {
  wrap:    { display:'flex', height:'100vh', fontFamily:'Montserrat, sans-serif', overflow:'hidden' },
  sidebar: { width:220, background:'#1a2b4b', display:'flex', flexDirection:'column', flexShrink:0 },
  logo:    { padding:'20px 16px 16px', borderBottom:'1px solid rgba(255,255,255,0.1)' },
  logoRow: { display:'flex', alignItems:'center', gap:10 },
  logoIcon:{ width:34, height:34, background:'#2d4a7a', borderRadius:8, display:'flex', alignItems:'center', justifyContent:'center', fontSize:16 },
  logoTxt: { color:'#fff', fontWeight:700, fontSize:13, lineHeight:1.3 },
  logoSub: { color:'rgba(255,255,255,0.4)', fontSize:10 },
  nav:     { flex:1, padding:'12px 8px', overflowY:'auto' },
  navSec:  { color:'rgba(255,255,255,0.3)', fontSize:9, fontWeight:700, letterSpacing:'0.08em', textTransform:'uppercase', padding:'8px 8px 4px' },
  main:    { flex:1, display:'flex', flexDirection:'column', overflow:'hidden', background:'#f1f2f3' },
  topbar:  { height:52, background:'#fff', borderBottom:'1px solid #ebeced', display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 20px', flexShrink:0 },
  content: { flex:1, overflowY:'auto', padding:20 },
  userRow: { padding:'8px', borderTop:'1px solid rgba(255,255,255,0.1)' },
  avatar:  { width:32, height:32, borderRadius:'50%', background:'#2d4a7a', display:'flex', alignItems:'center', justifyContent:'center', color:'#fff', fontSize:11, fontWeight:700, flexShrink:0 },
};

export default function AdminLayout({ children }) {
  const { profile, logout } = useAuth();
  const navigate = useNavigate();

  async function handleLogout() {
    await logout();
    navigate('/login');
  }

  const initials = profile?.nama
    ? profile.nama.split(' ').map(w => w[0]).slice(0,2).join('').toUpperCase()
    : 'FM';

  return (
    <div style={S.wrap}>
      {/* Sidebar */}
      <div style={S.sidebar}>
        <div style={S.logo}>
          <div style={S.logoRow}>
            <div style={S.logoIcon}>🚛</div>
            <div>
              <div style={S.logoTxt}>FleetMate</div>
              <div style={S.logoSub}>PT. MMS · Admin</div>
            </div>
          </div>
        </div>

        <nav style={S.nav}>
          <div style={S.navSec}>Menu Utama</div>
          {NAV.map(item => (
            <NavLink key={item.to} to={item.to} end={item.exact}
              style={({ isActive }) => ({
                display:'flex', alignItems:'center', gap:10,
                padding:'9px 10px', borderRadius:8,
                cursor:'pointer', fontSize:12, fontWeight:500,
                marginBottom:1, textDecoration:'none',
                transition:'all 0.15s',
                background: isActive ? '#2d4a7a' : 'transparent',
                color: isActive ? '#fff' : 'rgba(255,255,255,0.6)',
              })}>
              <span>{item.icon}</span>
              {item.label}
            </NavLink>
          ))}
        </nav>

        <div style={S.userRow}>
          <div style={{ display:'flex', alignItems:'center', gap:8, padding:'8px 10px', borderRadius:8, cursor:'pointer' }}
               onMouseOver={e => e.currentTarget.style.background = 'rgba(255,255,255,0.07)'}
               onMouseOut={e  => e.currentTarget.style.background = 'transparent'}>
            <div style={S.avatar}>{initials}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ color:'#fff', fontSize:11, fontWeight:600, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                {profile?.nama || 'Admin'}
              </div>
              <div style={{ color:'rgba(255,255,255,0.4)', fontSize:10, textTransform:'capitalize' }}>
                {profile?.role || 'admin'}
              </div>
            </div>
            <button onClick={handleLogout} title="Logout"
              style={{ background:'none', border:'none', cursor:'pointer', color:'rgba(255,255,255,0.3)', fontSize:16, padding:2 }}>
              ↩
            </button>
          </div>
        </div>
      </div>

      {/* Main */}
      <div style={S.main}>
        <div style={S.topbar}>
          <div style={{ display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ width:7, height:7, borderRadius:'50%', background:'#10b981', display:'inline-block' }}/>
            <span style={{ color:'#10b981', fontSize:11, fontWeight:600 }}>Realtime</span>
            <span style={{ color:'#c4c7cf', fontSize:11 }}>·</span>
            <span style={{ color:'#74777f', fontSize:11 }}>
              {new Date().toLocaleDateString('id-ID', { weekday:'long', day:'numeric', month:'long', year:'numeric' })}
            </span>
          </div>
          <span style={{ fontSize:12, color:'#44474e', fontWeight:600 }}>
            {new Date().toLocaleTimeString('id-ID', { hour:'2-digit', minute:'2-digit' })}
          </span>
        </div>
        <div style={S.content}>{children}</div>
      </div>
    </div>
  );
}
